python
def positiveTraysPositiveInkInvoice(readings):
    a=readings
    out=[]
    for x in a:
        if x>0: out.append(x)
    return sum(x for x in out if x>0)


java
class Solution {
  public int positiveTraysPositiveInkInvoice(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a)if(x>0)out.add(x);}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
